<section class="page-head compact"><div class="container page-head-inner"><div><div class="eyebrow">Owner tools</div><h1>Booking <em>masuk.</em></h1><p>Konfirmasi dan pantau semua jadwal bermain di lapanganmu.</p></div><a class="btn btn-ghost" href="<?= url('calendar') ?>">Buka kalender ↗</a></div></section>
<section class="section section-light"><div class="container"><div class="table-card"><div class="table-card-head"><h2>Semua booking</h2><span class="muted"><?= count($bookings) ?> data</span></div><?php if ($bookings): ?><div class="responsive-table"><table><thead><tr><th>Pemain</th><th>Lapangan</th><th>Jadwal</th><th>Total</th><th>Status</th><th>Ubah</th></tr></thead><tbody><?php foreach ($bookings as $booking): ?><tr><td><strong><?= e($booking['customer_name']) ?></strong><small><?= e($booking['customer_email']) ?></small></td><td><?= e($booking['field_name']) ?><small><?= e($booking['city']) ?></small></td><td><?= formatDateId($booking['booking_date']) ?><small><?= substr($booking['start_time'], 0, 5) ?>–<?= substr($booking['end_time'], 0, 5) ?></small></td><td><?= formatRupiah($booking['total_price']) ?></td><td><span class="badge <?= statusClass($booking['status']) ?>"><?= statusLabel($booking['status']) ?></span></td><td><form method="post" action="<?= url('admin/booking/status') ?>" class="inline-form"><input type="hidden" name="_csrf" value="<?= csrf_token() ?>"><input type="hidden" name="id" value="<?= e($booking['id']) ?>"><select name="status" aria-label="Status booking"><option value="pending" <?= $booking['status'] === 'pending' ? 'selected' : '' ?>>Menunggu</option><option value="confirmed" <?= $booking['status'] === 'confirmed' ? 'selected' : '' ?>>Konfirmasi</option><option value="completed" <?= $booking['status'] === 'completed' ? 'selected' : '' ?>>Selesai</option><option value="cancelled" <?= $booking['status'] === 'cancelled' ? 'selected' : '' ?>>Batalkan</option></select><button class="btn-link" type="submit">Simpan</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state compact-empty"><div class="empty-icon">◌</div><h3>Belum ada booking</h3><p>Booking dari pemain akan muncul di sini.</p></div><?php endif; ?></div></div></section>
